            workspaceId: String? = null,
            requestOptions: RequestOptions = RequestOptions.Default,
        ): ApiResponse<Unit> =
            engine.empty(
                RequestSpec(
                    method = "POST",
                    path = "/v1/workspaces/" + pathSegment("workspaceId", engine.workspaceId(workspaceId)) + "/webhooks/messages/" + pathSegment("id", id) + "/resend",
                    auth = AuthMode.KEY,
                    payload = engine.jsonPayload(WebhookResend.serializer(), body),
                    idempotent = true,
                ),
                requestOptions,
            )

        /**
         * Счётчик событий месяца
         *
         * `GET /v1/workspaces/{ws}/webhooks/usage`
         *
         * Required permission: `Владелец или админ workspace; ключ API — с правом webhooks.manage`.
         *
         * @param workspaceId the workspace; by default the workspace of the client
         */
        public suspend fun getUsage(
            workspaceId: String? = null,
            requestOptions: RequestOptions = RequestOptions.Default,
        ): ApiResponse<WebhookUsage> =
            engine.json(
                RequestSpec(
                    method = "GET",
                    path = "/v1/workspaces/" + pathSegment("workspaceId", engine.workspaceId(workspaceId)) + "/webhooks/usage",
                    auth = AuthMode.KEY,
                ),
                requestOptions,
                WebhookUsage.serializer(),
            )
    }
}
